"""
This python module provides a console interface to collect the bip trace without using
robot directly from the command line. The command line call 'collect_bip_trace' uses the
functionality of the library to collect the bip traces for manual testing.

The idea is, that the tester has an easy interface to retrieve the pcap file for a bip trace.

For help on how to use the interface use the command line call

$ collect_bip_trace --help
"""
import importlib
import os
import subprocess
import sys
import argparse
import logging
from . import bip_config
from . import bip_trace

HELP_TEXT = """Collect the resource from the NodeB

the information on how to connect to the nodeb is retrieved from the testline
configuration. You need provide the testline configuration by the path to the
testline respository and the testline name.
By default, the current host name is derived to formulate the testline name and
the testline configuration repository is expected to be in /home/ute/testline_configuration

If You do not have a local checkout of the testline_configuration, you can clone it from:
git@wrgitlab.ext.net.nokia.com:RAN/configuration-management/testline_configuration.git
"""
logger = logging.getLogger()


def setup_logging(directory, loglevel):
    """
    This function is setting up the logging for the bip collection. A file will be created
    in the same location as the recorded bip trace with the name 'bip_trace_collection.log'

    :param directory: The directory where to place the log file
    :param loglevel: The loglevel for log collection, can be INFO, DEBUG, WARNING, ERROR
    """

    try:
        logging_level = {'INFO': logging.INFO,
                         'DEBUG': logging.DEBUG,
                         'WARNING': logging.WARNING,
                         'ERROR': logging.ERROR,
                         'CRITICAL': logging.CRITICAL}[loglevel.upper()]
    except KeyError:
        raise AssertionError("Unknown loglevel {}!".format(loglevel))

    log_file = os.path.join(directory, "bip_trace_collection.log")

    root_logger = logging.getLogger()
    root_logger.setLevel(logging_level)
    log_formatter = logging.Formatter("%(asctime)s [%(threadName)-12.12s] [%(levelname)-5.5s] %(message)s")

    file_handler = logging.FileHandler(log_file, mode="w")
    file_handler.setFormatter(log_formatter)
    root_logger.addHandler(file_handler)


def get_tl_name_from_host():
    """Get the testline name by the hostname"""
    host_name, _ = subprocess.Popen(['hostname'], stdout=subprocess.PIPE).communicate()
    return host_name.decode('UTF-8').strip().replace('-', '_')


def import_config_module(module_name, tl_config_path):
    """Import the testline configuration. The python path is udated, so the testine configuration
    is found within the given path of the testline config repository

    :param module_name: The module to import containing the testline configuration
    :param tl_config_path: The path to the testline configuration repository
    """
    if not os.path.exists(tl_config_path):
        raise AssertionError('The path does not exist: [{}] repository of testline_configuration not found!'.
                             format(tl_config_path))
    sys.path.append(tl_config_path)
    return importlib.import_module(module_name)


def load_local_testline_config(tl_config_path, tl_name=None):
    """Imports the testline configuration from the __init__.py configuration file
    :param tl_config_path: the path to the testline configuration repository
    :param tl_name: The name of the testline, corresponding to the foldername of the tl
    """
    if tl_name is None:
        module_name = get_tl_name_from_host()
    else:
        module_name = tl_name

    try:
        mm = import_config_module(module_name, tl_config_path)
        return mm.tl
    except ImportError:
        raise AssertionError("No testline configuration found!!")


def read_input(query_string):
    """Query information from user

    :param query_string: String to prompt to user
    """
    return input(query_string)


def parse_arguments():
    """Parses the arguments of the console script call
    """
    parser = argparse.ArgumentParser(prog='collect_bip_trace',
                                     description=HELP_TEXT,
                                     epilog='Resource collection',
                                     formatter_class=argparse.RawTextHelpFormatter)
    parser.add_argument('-i', '--gnbid', default='0',
                        help='The array index of the gNodeB in the tl config (default: 0)')
    parser.add_argument('-c', '--tlconfigpath',
                        default='/home/ute/testline_configuration',
                        help='Path to tl config repository, default: /home/ute/testline_configuration')
    parser.add_argument('-n', '--tlname', help='Name of the testline (by default taken from hostname)')
    parser.add_argument('-l', '--loglevel',
                        help='The log level of the output',
                        default='INFO')

    parser.add_argument('target_dir', help='The path to save the bip trace to')

    args = parser.parse_args()

    return args


def collect_bip_trace():
    args = parse_arguments()
    logging.info("Preparing collection of BIP trace....")

    setup_logging(args.target_dir, args.loglevel)
    bip_config.TL_CONFIG = load_local_testline_config(tl_config_path=args.tlconfigpath,
                                                      tl_name=args.tlname)
    gnb_id = int(args.gnbid)
    bip_trace.start_bip_trace(gnb_id=gnb_id)
    logging.info("Collecting BIP trace....")

    read_input("Press [Enter] to stop recording the bip trace!")

    logging.info("Stopping and collecting BIP trace ...")
    recorded_trace = bip_trace.stop_bip_trace(gnb_id=gnb_id, target_dir=args.target_dir)

    logging.info("The BIP trace was written to {}".format(recorded_trace))
